/**
 * AID — unit, property and fuzz tests, plus the canonical test vectors.
 *
 * The vectors at the top are generated by this file and committed, so a later change to the
 * implementation that alters any of them fails here rather than silently forking the
 * identifier scheme.
 */

import test from 'node:test';
import assert from 'node:assert/strict';

import {
  SPEC_VERSION, DEFAULT_CHAIN_ID, AssetType, AidError,
  domainSeparator, assetId, nativeId, erc20Id, erc721Id, erc1155Id,
  toCanonicalString, fromCanonicalString, nftKey, addressToWord, word256,
} from '../src/aid.mjs';

const NEXORA_PRECOMPILE = '0xeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee';
const ZERO = '0x0000000000000000000000000000000000000000';
const TOKEN = '0x1111111111111111111111111111111111111111';

// ---------------------------------------------------------------- test vectors

test('canonical test vectors are stable', () => {
  const vectors = [
    ['NATIVE', toCanonicalString(nativeId())],
    ['ERC20 zero address', toCanonicalString(erc20Id(ZERO))],
    ['ERC20 native precompile', toCanonicalString(erc20Id(NEXORA_PRECOMPILE))],
    ['ERC721 #1 tokenId 0', toCanonicalString(erc721Id(TOKEN, 0))],
    ['ERC721 #2 tokenId 1', toCanonicalString(erc721Id(TOKEN, 1))],
    ['ERC1155 #3 tokenId 77', toCanonicalString(erc1155Id(TOKEN, 77))],
    ['NATIVE on chainId 1', toCanonicalString(nativeId(1))],
  ];
  // Print them so they can be pasted into aid/SPEC.md and the Solidity test.
  for (const [name, id] of vectors) console.log(`  ${name.padEnd(26)} ${id}`);

  for (const [name, id] of vectors) {
    assert.match(id, /^[0-9a-f]{64}$/, `${name} is not in canonical form`);
  }
  // Chain binding must actually separate domains.
  assert.notEqual(toCanonicalString(nativeId()), toCanonicalString(nativeId(1)));
  // Token id must actually matter.
  assert.notEqual(toCanonicalString(erc721Id(TOKEN, 0)), toCanonicalString(erc721Id(TOKEN, 1)));
  // ERC721 and ERC1155 must not collide.
  assert.notEqual(toCanonicalString(erc721Id(TOKEN, 77)), toCanonicalString(erc1155Id(TOKEN, 77)));
});

// ---------------------------------------------------------------- domain separation

test('domainSeparator binds the chain id and the spec version', () => {
  assert.notEqual(toCanonicalString(domainSeparator(902024)), toCanonicalString(domainSeparator(1)));
  assert.notEqual(toCanonicalString(domainSeparator(902024, 1)), toCanonicalString(domainSeparator(902024, 2)));
  assert.equal(toCanonicalString(domainSeparator(902024)), toCanonicalString(domainSeparator(902024, SPEC_VERSION)));
});

test('the preimage is exactly 66 bytes, so no two encodings can alias', () => {
  // width check on the inputs that feed the hash
  assert.equal(word256(0).length, 32);
  assert.equal(word256((1n << 256n) - 1n).length, 32);
  assert.equal(addressToWord(ZERO).length, 32);
  assert.equal(nftKey(TOKEN, 0).length, 32);
});

test('the native coin is zero-padded on the left and the precompile is right-aligned', () => {
  assert.equal(toCanonicalString(addressToWord(ZERO)), '0'.repeat(64));
  // 20 bytes of 0xee right-aligned in a 32-byte word: 24 leading zeros, then 40 hex chars.
  assert.equal(
    toCanonicalString(addressToWord(NEXORA_PRECOMPILE)),
    '0'.repeat(24) + 'ee'.repeat(20)
  );
});

// ---------------------------------------------------------------- validation

test('an unknown asset type is rejected, not hashed', () => {
  for (const bad of [-1, 4, 255, 1.5, '0x01']) {
    assert.throws(() => assetId(bad, new Uint8Array(32)), AidError, `type ${bad} must be rejected`);
  }
});

test('a malformed address is rejected', () => {
  for (const bad of ['0x1234', 'not-an-address', '0x' + 'z'.repeat(40), '', '0x' + '1'.repeat(42)]) {
    assert.throws(() => erc20Id(bad), AidError, `address ${bad} must be rejected`);
  }
});

test('an address is case-insensitive, as hex should be', () => {
  assert.equal(toCanonicalString(erc20Id(TOKEN)), toCanonicalString(erc20Id(TOKEN.toUpperCase().replace('0X', '0x'))));
});

test('an assetKey that is not 32 bytes is rejected', () => {
  assert.throws(() => assetId(AssetType.ERC20, new Uint8Array(31)), AidError);
  assert.throws(() => assetId(AssetType.ERC20, new Uint8Array(33)), AidError);
});

test('a value outside uint256 is rejected', () => {
  assert.throws(() => word256(-1), AidError);
  assert.throws(() => word256(1n << 256n), AidError);
  assert.throws(() => word256(1.5), AidError);
});

test('uint256 boundaries encode correctly', () => {
  assert.equal(toCanonicalString(word256(0)), '0'.repeat(64));
  assert.equal(toCanonicalString(word256(1)), '0'.repeat(63) + '1');
  assert.equal(toCanonicalString(word256(255)), '0'.repeat(62) + 'ff');
  assert.equal(toCanonicalString(word256((1n << 256n) - 1n)), 'f'.repeat(64));
});

test('token ids beyond uint64 are handled, not truncated', () => {
  const big = (1n << 200n) + 12345n;
  assert.notEqual(toCanonicalString(erc721Id(TOKEN, big)), toCanonicalString(erc721Id(TOKEN, 12345n)));
});

// ---------------------------------------------------------------- canonical text form

test('the canonical string form round-trips and is strict', () => {
  const id = nativeId();
  assert.deepEqual(Array.from(fromCanonicalString(toCanonicalString(id))), Array.from(id));
  for (const bad of ['0x' + 'a'.repeat(64), 'A'.repeat(64), 'a'.repeat(63), 'a'.repeat(65), '', 'zz', '0x']) {
    assert.throws(() => fromCanonicalString(bad), AidError, `${bad} must be rejected`);
  }
});

test('uppercase is rejected at the boundary rather than normalised, as the spec requires', () => {
  const lower = toCanonicalString(nativeId());
  assert.throws(() => fromCanonicalString(lower.toUpperCase()), AidError);
});

// ---------------------------------------------------------------- determinism

test('the same input always yields the same identifier', () => {
  for (let i = 0; i < 200; i++) {
    assert.equal(toCanonicalString(erc721Id(TOKEN, i)), toCanonicalString(erc721Id(TOKEN, i)));
  }
});

// ---------------------------------------------------------------- property: every field matters

test('changing any single field changes the assetId', () => {
  const base = toCanonicalString(erc721Id(TOKEN, 5));
  assert.notEqual(base, toCanonicalString(erc721Id(TOKEN, 6)), 'tokenId must matter');
  assert.notEqual(base, toCanonicalString(erc721Id(NEXORA_PRECOMPILE, 5)), 'address must matter');
  assert.notEqual(base, toCanonicalString(erc1155Id(TOKEN, 5)), 'type must matter');
  assert.notEqual(base, toCanonicalString(erc721Id(TOKEN, 5, 1)), 'chainId must matter');
});

test('the preimage is injective over the fields that vary', () => {
  // Same key, every type: 4 distinct ids. Any aliasing here would mean two different
  // assets resolve to one identifier.
  const key = new Uint8Array(32).fill(7);
  const ids = new Set([0, 1, 2, 3].map((t) => toCanonicalString(assetId(t, key))));
  assert.equal(ids.size, 4);
});

// ---------------------------------------------------------------- fuzz

test('fuzz: no two distinct asset tuples share an assetId', () => {
  // Deterministic pseudo-random generator: a failing seed is reproducible from the message.
  let seed = 0x9e3779b9;
  const rnd = () => {
    seed ^= seed << 13; seed >>>= 0;
    seed ^= seed >>> 17;
    seed ^= seed << 5; seed >>>= 0;
    return seed;
  };
  const seen = new Map();
  const emitted = new Set();
  const chains = [DEFAULT_CHAIN_ID, 1, 5, 11155111, 902024];
  for (let i = 0; i < 20000; i++) {
    // `& 0xffffffff` is a SIGNED bitwise op in JS: it yields a negative number and
    // toString(16) renders it as '-510c4619', which is not an address. `>>> 0` is unsigned.
    // Five groups of eight hex characters = 40 characters = the 20 bytes an address needs.
    const hex8 = () => (rnd() >>> 0).toString(16).padStart(8, '0');
    const addr = '0x' + hex8() + hex8() + hex8() + hex8() + hex8();
    const tokenId = BigInt(rnd() >>> 0) * BigInt((rnd() >>> 0) + 1);
    const chain = chains[rnd() % chains.length];
    const tuples = [
      ['NATIVE', nativeId(chain), `native:${chain}`],
      ['ERC20', erc20Id(addr, chain), `erc20:${addr}:${chain}`],
      ['ERC721', erc721Id(addr, tokenId, chain), `erc721:${addr}:${tokenId}:${chain}`],
      ['ERC1155', erc1155Id(addr, tokenId, chain), `erc1155:${addr}:${tokenId}:${chain}`],
    ];
    for (const [kind, bytes, label] of tuples) {
      // Two DISTINCT tuples must not collide. The same tuple appearing twice is not a
      // collision, it is determinism, and it is asserted separately. Skipping repeats is
      // what makes this test mean what it says.
      if (emitted.has(label)) continue;
      emitted.add(label);
      const id = toCanonicalString(bytes);
      if (seen.has(id)) {
        assert.fail(`collision: ${kind} ${label} == ${seen.get(id)}`);
      }
      seen.set(id, `${kind} ${label}`);
    }
  }
  assert.ok(seen.size >= 40000, `expected many distinct ids, got ${seen.size}`);
});

test('fuzz: canonical text form is always exactly 64 lowercase hex characters', () => {
  let seed = 0x12345678;
  const rnd = () => { seed = (seed * 1103515245 + 12345) >>> 0; return seed; };
  for (let i = 0; i < 5000; i++) {
    const key = new Uint8Array(32);
    for (let b = 0; b < 32; b++) key[b] = rnd() & 0xff;
    const id = toCanonicalString(assetId(rnd() % 4, key, 1 + (rnd() % 1000)));
    assert.match(id, /^[0-9a-f]{64}$/);
  }
});

test('fuzz: arbitrary key bytes never throw', () => {
  let seed = 0xfeedbeef;
  const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed; };
  for (let i = 0; i < 5000; i++) {
    const key = new Uint8Array(32);
    for (let b = 0; b < 32; b++) key[b] = rnd() & 0xff;
    const id = toCanonicalString(assetId(rnd() % 4, key));
    assert.match(id, /^[0-9a-f]{64}$/);
  }
});